<?php
/** Semaphore SMS service. Failures are returned to the caller and never thrown into an order flow. */
class SmsService {
    private $apiKey; private $sender;
    public function __construct(){ $this->apiKey=$_ENV['SEMAPHORE_API_KEY']??''; $this->sender=$_ENV['SEMAPHORE_SENDER_NAME']??''; }
    public static function normalizePhilippineMobile($number){$n=preg_replace('/\D/','',(string)$number);if(preg_match('/^09\d{9}$/',$n))return '+63'.substr($n,1);if(preg_match('/^639\d{9}$/',$n))return '+'.$n;if(preg_match('/^9\d{9}$/',$n))return '+63'.$n;return null;}
    public function send($number,$message){$number=self::normalizePhilippineMobile($number);if(!$number)return ['ok'=>false,'error'=>'Invalid Philippine mobile number.'];if(!$this->apiKey||!$this->sender)return ['ok'=>false,'error'=>'SMS service is not configured.'];$ch=curl_init('https://api.semaphore.co/api/v4/messages');curl_setopt_array($ch,[CURLOPT_POST=>true,CURLOPT_POSTFIELDS=>http_build_query(['apikey'=>$this->apiKey,'number'=>$number,'message'=>$message,'sendername'=>$this->sender]),CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15]);$body=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);$error=curl_error($ch);curl_close($ch);$data=json_decode($body,true);$item=is_array($data)&&isset($data[0])?$data[0]:$data;$id=is_array($item)?($item['message_id']??$item['id']??null):null;return ['ok'=>$code>=200&&$code<300&&empty($error),'id'=>$id,'error'=>$error?:($code>=300?'Semaphore HTTP '.$code:null)];}
}
function sendStudentSmsNotification($conn,$studentId,$referenceType,$referenceId,$notificationType,$message){$check=$conn->prepare('SELECT id FROM sms_notifications WHERE student_id=? AND reference_type=? AND reference_id=? AND notification_type=? LIMIT 1');$check->bind_param('isis',$studentId,$referenceType,$referenceId,$notificationType);$check->execute();$exists=$check->get_result()->fetch_assoc();$check->close();if($exists)return false;$student=$conn->prepare('SELECT contact,sms_notifications_enabled FROM students WHERE id=?');$student->bind_param('i',$studentId);$student->execute();$user=$student->get_result()->fetch_assoc();$student->close();if(!$user||!(int)$user['sms_notifications_enabled'])return false;$number=SmsService::normalizePhilippineMobile($user['contact']);$insert=$conn->prepare('INSERT INTO sms_notifications(student_id,reference_type,reference_id,mobile_number,notification_type,message,status,error_message) VALUES(?,?,?,?,?,?,?,?)');$status=$number?'pending':'failed';$error=$number?null:'Invalid Philippine mobile number.';$insert->bind_param('isisssss',$studentId,$referenceType,$referenceId,$number,$notificationType,$message,$status,$error);$insert->execute();$id=$insert->insert_id;$insert->close();if(!$number)return false;$result=(new SmsService())->send($number,$message);$status=$result['ok']?'sent':'failed';$provider=$result['id']??null;$error=$result['error']??null;$update=$conn->prepare('UPDATE sms_notifications SET provider_message_id=?,status=?,error_message=?,sent_at=IF(?="sent",NOW(),NULL) WHERE id=?');$update->bind_param('ssssi',$provider,$status,$error,$status,$id);$update->execute();$update->close();return $result['ok'];}
